<template>
  <div class="business-page">
    <aside class="sidebar">
      <div><p class="eyebrow">Structured operations</p><h1>Business Data</h1></div>
      <nav class="tabs"><button v-for="tab in tabs" :key="tab.id" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id"><span>{{ tab.icon }}</span>{{ tab.label }}</button></nav>
      <button class="secondary-btn" @click="router.push({ name: 'dashboard' })">Back to Dashboard</button>
    </aside>
    <main class="content">
      <header class="topbar"><div><p class="eyebrow">Clean data capture</p><h2>{{ activeTitle }}</h2></div><button v-if="activeTab === 'sales'" class="primary-btn" @click="createTrainingDataset" :disabled="isCreatingDataset">{{ isCreatingDataset ? 'Creating...' : 'Create Training Dataset' }}</button></header>
      <div v-if="error" class="notice error">{{ error }}</div><div v-if="success" class="notice success">{{ success }}</div>

      <section v-if="activeTab === 'products'" class="workspace-grid">
        <form class="panel" @submit.prevent="saveProduct"><p class="eyebrow">Product catalog</p><h3>Add Product</h3><div class="form-grid"><label>SKU<input v-model="productForm.sku" required /></label><label>Name<input v-model="productForm.name" required /></label><label>Category<input v-model="productForm.category" /></label><label>Supplier<input v-model="productForm.supplier_name" /></label><label>Unit Cost<input v-model.number="productForm.unit_cost" type="number" min="0" step="0.01" /></label><label>Current Price<input v-model.number="productForm.current_price" type="number" min="0" step="0.01" /></label><label>Store Inventory<input v-model.number="productForm.current_inventory" type="number" min="0" /></label><label>Warehouse Stock<input v-model.number="productForm.warehouse_stock" type="number" min="0" /></label><label>Lead Time Days<input v-model.number="productForm.supplier_lead_time_days" type="number" min="0" /></label><label>Safety Stock<input v-model.number="productForm.safety_stock_units" type="number" min="0" /></label></div><button class="primary-btn" type="submit" :disabled="isSavingProduct">{{ isSavingProduct ? 'Saving...' : 'Save Product' }}</button></form>
        <section class="panel"><p class="eyebrow">{{ products.length }} products</p><h3>Products</h3><div v-if="!products.length" class="empty">Add products before logging sales or running product intelligence.</div><div v-else class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Price</th><th>Inventory</th><th>Supplier</th></tr></thead><tbody><tr v-for="product in products" :key="product.id"><td>{{ product.name }}</td><td>{{ product.sku }}</td><td>{{ '$' + money(product.current_price) }}</td><td>{{ product.current_inventory }} + {{ product.warehouse_stock }}</td><td>{{ product.supplier_name || 'Unassigned' }}</td></tr></tbody></table></div></section>
      </section>

      <section v-if="activeTab === 'sales'" class="workspace-grid">
        <form class="panel" @submit.prevent="saveSale"><p class="eyebrow">Sales logging</p><h3>Log Sale</h3><div class="form-grid"><label class="span-2">Product<select v-model.number="saleForm.product_id" required><option value="" disabled>Select product</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.name }} ({{ product.sku }})</option></select></label><label>Date<input v-model="saleForm.sale_date" type="datetime-local" /></label><label>Quantity<input v-model.number="saleForm.quantity" type="number" min="1" required /></label><label>Unit Price<input v-model.number="saleForm.unit_price" type="number" min="0" step="0.01" required /></label><label>Discount<input v-model.number="saleForm.discount_amount" type="number" min="0" step="0.01" /></label><label>Customer<input v-model="saleForm.customer_name" /></label><label>Customer Segment<input v-model="saleForm.customer_segment" /></label><label>Channel<input v-model="saleForm.channel" /></label><label>Campaign<input v-model="saleForm.campaign_name" /></label><label class="span-2">Notes<input v-model="saleForm.notes" /></label></div><button class="primary-btn" type="submit" :disabled="isSavingSale || !products.length">{{ isSavingSale ? 'Logging...' : 'Log Sale' }}</button></form>
        <section class="panel"><p class="eyebrow">{{ sales.length }} recent logs</p><h3>Sales Ledger</h3><div v-if="!sales.length" class="empty">No sales logged yet. Structured entries here replace messy spreadsheet dependency.</div><div v-else class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Qty</th><th>Price</th><th>Revenue</th><th>Campaign</th></tr></thead><tbody><tr v-for="sale in sales" :key="sale.id"><td>{{ shortDate(sale.sale_date) }}</td><td>{{ sale.product_name }}</td><td>{{ sale.quantity }}</td><td>{{ '$' + money(sale.unit_price) }}</td><td>{{ '$' + money(sale.revenue) }}</td><td>{{ sale.campaign_name || '-' }}</td></tr></tbody></table></div></section>
      </section>

      <section v-if="activeTab === 'intelligence'" class="intelligence-space"><div class="overview-grid"><article class="metric-card"><p>Products</p><strong>{{ summary?.counts?.products || 0 }}</strong></article><article class="metric-card"><p>Sales Logs</p><strong>{{ summary?.counts?.sales_logs || 0 }}</strong></article><article class="metric-card"><p>Customers</p><strong>{{ summary?.counts?.customers || 0 }}</strong></article><article class="metric-card"><p>Campaign Sales</p><strong>{{ summary?.counts?.campaign_sales || 0 }}</strong></article></div><div class="module-grid"><article v-for="module in moduleCards" :key="module.id" class="panel module-card"><p class="eyebrow">{{ module.status }}</p><h3>{{ module.name }}</h3><p class="module-summary">{{ module.summary }}</p><ul><li v-for="item in module.highlights" :key="item">{{ item }}</li></ul></article></div><section class="panel"><p class="eyebrow">Business Intelligence Copilot</p><h3>Root Cause Path</h3><ol class="root-cause"><li v-for="step in summary?.modules?.copilot?.root_cause_path || []" :key="step.area"><span>{{ step.area }}</span><strong>{{ step.finding }}</strong></li></ol></section><section class="panel"><p class="eyebrow">Autonomous Business Agents</p><h3>Workflow Status</h3><div class="agent-grid"><article v-for="agent in summary?.modules?.agents?.workflow || []" :key="agent.name" class="agent-card"><span :class="['agent-dot', agent.state]"></span><h4>{{ agent.name }}</h4><p>{{ agent.task }}</p></article></div></section></section>
    </main>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import api from '@/services/api'
const router = useRouter(); const activeTab = ref('products'); const products = ref([]); const sales = ref([]); const summary = ref(null); const error = ref(''); const success = ref(''); const isSavingProduct = ref(false); const isSavingSale = ref(false); const isCreatingDataset = ref(false)
const tabs = [{ id: 'products', label: 'Products', icon: 'P' }, { id: 'sales', label: 'Sales Log', icon: 'S' }, { id: 'intelligence', label: 'Intelligence', icon: 'I' }]
const blankProduct = () => ({ sku: '', name: '', category: '', supplier_name: '', unit_cost: 0, current_price: 0, current_inventory: 0, warehouse_stock: 0, supplier_lead_time_days: 7, safety_stock_units: 0, reorder_point_units: 0 })
const blankSale = () => ({ product_id: '', sale_date: '', quantity: 1, unit_price: 0, discount_amount: 0, customer_name: '', customer_segment: '', channel: '', campaign_name: '', notes: '' })
const productForm = ref(blankProduct()); const saleForm = ref(blankSale())
const activeTitle = computed(() => tabs.find((tab) => tab.id === activeTab.value)?.label || 'Business Data')
const moduleCards = computed(() => { const modules = summary.value?.modules || {}; return [moduleCard('pricing', 'Pricing Intelligence', modules.pricing), moduleCard('inventory', 'Inventory Intelligence', modules.inventory), moduleCard('product', 'Product Intelligence', modules.product), moduleCard('customer', 'Customer Intelligence', modules.customer), moduleCard('marketing', 'Marketing Intelligence', modules.marketing), moduleCard('procurement', 'Procurement Intelligence', modules.procurement)] })
onMounted(async () => { await Promise.all([fetchProducts(), fetchSales(), fetchSummary()]) })
function moduleCard(id, name, module) { const items = module?.items || module?.metrics || []; const highlights = items.slice(0, 4).map((item) => { if (item.product && item.recommended_purchase_quantity !== undefined) return item.product + ': buy ' + item.recommended_purchase_quantity + ', cover ' + item.days_cover; if (item.product && item.margin_rate !== undefined) return item.product + ': margin ' + (item.margin_rate * 100).toFixed(1) + '%, lifecycle ' + item.lifecycle; if (item.customer) return item.customer + ': ' + item.segment + ', churn ' + item.churn_risk; if (item.supplier) return item.supplier + ': ' + item.supplier_risk + ' risk, buy ' + item.purchase_optimization; if (item.label) return item.label + ': ' + item.value; return JSON.stringify(item) }); return { id, name, status: module?.status || 'Needs data', summary: module?.summary || 'Add structured data to activate this module.', highlights: highlights.length ? highlights : ['Add products and sales logs to generate recommendations.'] } }
async function fetchProducts() { const response = await api.get('/business/products'); products.value = response.data }
async function fetchSales() { const response = await api.get('/business/sales'); sales.value = response.data }
async function fetchSummary() { const response = await api.get('/business/intelligence/summary'); summary.value = response.data }
async function saveProduct() { clearMessages(); isSavingProduct.value = true; try { await api.post('/business/products', productForm.value); success.value = 'Product saved.'; productForm.value = blankProduct(); await Promise.all([fetchProducts(), fetchSummary()]) } catch (err) { error.value = err.response?.data?.detail || 'Could not save product.' } finally { isSavingProduct.value = false } }
async function saveSale() { clearMessages(); isSavingSale.value = true; try { const payload = { ...saleForm.value, sale_date: saleForm.value.sale_date || null }; await api.post('/business/sales', payload); success.value = 'Sale logged.'; saleForm.value = blankSale(); await Promise.all([fetchProducts(), fetchSales(), fetchSummary()]) } catch (err) { error.value = err.response?.data?.detail || 'Could not log sale.' } finally { isSavingSale.value = false } }
async function createTrainingDataset() { clearMessages(); isCreatingDataset.value = true; try { const response = await api.post('/business/sales/training-dataset'); success.value = response.data.message + ' ' + response.data.rows + ' rows are ready for model training.' } catch (err) { error.value = err.response?.data?.detail || 'Could not create training dataset.' } finally { isCreatingDataset.value = false } }
function clearMessages() { error.value = ''; success.value = '' } function money(value) { return Number(value || 0).toFixed(2) } function shortDate(value) { return new Date(value).toLocaleDateString() }
</script>
<style scoped>
.business-page { min-height: 100vh; background: #f4f6f8; color: #15202b; display: grid; grid-template-columns: 280px minmax(0, 1fr); } .sidebar { min-height: 100vh; background: #101820; color: white; padding: 24px; display: flex; flex-direction: column; gap: 24px; position: sticky; top: 0; } .eyebrow { margin: 0 0 6px; color: #687582; font-size: 12px; font-weight: 800; text-transform: uppercase; letter-spacing: 0; } .sidebar .eyebrow { color: #8ba3b6; } h1, h2, h3, h4 { margin: 0; } .tabs { display: flex; flex-direction: column; gap: 8px; } .tabs button { width: 100%; border: 0; border-radius: 8px; background: transparent; color: #c9d6df; padding: 10px; display: flex; align-items: center; gap: 10px; cursor: pointer; text-align: left; font-weight: 700; } .tabs button span { width: 28px; height: 28px; border-radius: 6px; display: grid; place-items: center; background: #24475c; color: #9de0c4; font-weight: 900; } .tabs button.active, .tabs button:hover { background: #1f3342; color: white; } .content { padding: 28px; display: flex; flex-direction: column; gap: 18px; } .topbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; } .primary-btn, .secondary-btn { border: 0; padding: 10px 16px; border-radius: 7px; cursor: pointer; font-weight: 800; } .primary-btn { background: #1f7a5c; color: white; } .primary-btn:disabled { background: #9aa6af; cursor: not-allowed; } .secondary-btn { background: white; color: #1f5f8b; border: 1px solid #cfd8df; margin-top: auto; } .notice { border-radius: 8px; padding: 12px 14px; font-weight: 700; } .notice.error { background: #fff0f0; color: #bb2d3b; border: 1px solid #ffd0d5; } .notice.success { background: #edf8f3; color: #1f7a5c; border: 1px solid #bfe6d5; } .workspace-grid { display: grid; grid-template-columns: minmax(320px, 0.8fr) minmax(0, 1.2fr); gap: 18px; } .panel, .metric-card { background: white; border: 1px solid #dce3e8; border-radius: 8px; box-shadow: 0 10px 28px rgba(16, 24, 32, 0.05); } .panel { padding: 22px; } .form-grid { margin: 18px 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; } label { display: flex; flex-direction: column; gap: 7px; color: #53616d; font-size: 13px; font-weight: 800; } input, select { min-height: 40px; border: 1px solid #cfd8df; border-radius: 7px; padding: 8px 10px; color: #15202b; } .span-2 { grid-column: span 2; } .table-wrap { overflow-x: auto; margin-top: 14px; } table { width: 100%; border-collapse: collapse; } th { background: #f4f6f8; color: #53616d; padding: 12px; text-align: left; font-size: 13px; } td { padding: 12px; border-bottom: 1px solid #edf1f4; font-size: 14px; } .empty { color: #687582; text-align: center; border: 1px dashed #cfd8df; border-radius: 8px; padding: 30px; margin-top: 14px; } .intelligence-space { display: flex; flex-direction: column; gap: 18px; } .overview-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; } .metric-card { padding: 18px; } .metric-card p { color: #687582; margin: 0 0 8px; } .metric-card strong { font-size: 28px; } .module-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; } .module-summary { color: #53616d; line-height: 1.5; } .module-card ul { margin: 14px 0 0; padding-left: 18px; color: #15202b; line-height: 1.8; } .root-cause { list-style: none; padding: 0; margin: 16px 0 0; display: flex; flex-direction: column; gap: 10px; } .root-cause li { display: flex; justify-content: space-between; gap: 16px; border-bottom: 1px solid #edf1f4; padding-bottom: 10px; } .root-cause span { color: #53616d; } .agent-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; margin-top: 16px; } .agent-card { border: 1px solid #dce3e8; border-radius: 8px; padding: 14px; min-height: 138px; } .agent-card p { color: #61707c; font-size: 13px; line-height: 1.45; } .agent-dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; background: #9aa6af; margin-bottom: 10px; } .agent-dot.active { background: #1f7a5c; } .agent-dot.ready { background: #1f5f8b; } .agent-dot.approval { background: #d49b20; } @media (max-width: 1100px) { .business-page { grid-template-columns: 1fr; } .sidebar { min-height: auto; position: static; } .tabs { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); } .workspace-grid, .module-grid, .agent-grid, .overview-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } } @media (max-width: 700px) { .content, .sidebar { padding: 18px; } .topbar { align-items: flex-start; flex-direction: column; } .tabs, .workspace-grid, .module-grid, .agent-grid, .overview-grid, .form-grid { grid-template-columns: 1fr; } .span-2 { grid-column: span 1; } }
</style>
